// ---- adjust here ---------------------------------------------
const BASE  = "http://AUTOPRINT-HOST:8080";  // e.g. http://192.168.1.20:8080
const TOKEN = "";                            // only if API_TOKEN is set in the container
// ----------------------------------------------------------------

const print = msg.topic !== "next";
msg.topic   = print ? "print" : "next";
msg.method  = print ? "POST" : "GET";
msg.url     = BASE + (print ? "/api/print" : "/api/next");
msg.headers = TOKEN ? { Authorization: "Bearer " + TOKEN } : {};
msg.payload = print ? {} : "";
msg.requestTimeout = 70000;   // printer may need ~45 s to wake up
if (print) node.status({ fill: "blue", shape: "dot", text: "druckt …" });
return msg;

// Output 1: notification (only after a print)
// Output 2: sensor "AutoPrint nächstes Bild"
const code = msg.statusCode;
const body = (msg.payload && typeof msg.payload === "object") ? msg.payload : {};
const next = body.next_image || "Farbtestseite";

let notify = null;
if (msg.topic === "print") {
    let title, text;
    if (code === 200 && body.ok) {
        title = "AutoPrint";
        text  = `Gedruckt: ${body.image || "Farbtestseite"}. Als Nächstes: ${next}.`;
        node.status({ fill: "green", shape: "dot", text: body.image || "Farbtestseite" });
    } else {
        title = "AutoPrint – Druck fehlgeschlagen";
        if (!code)             text = "AutoPrint ist nicht erreichbar (Container aus oder falsche Adresse).";
        else if (code === 409) text = "Es läuft gerade schon ein Druckauftrag.";
        else if (code === 401) text = "API-Token fehlt oder ist falsch.";
        else                   text = body.message || body.error || ("HTTP " + code);
        node.status({ fill: "red", shape: "ring", text: text.slice(0, 40) });
    }
    notify = { payload: { title, message: text } };
}

let sensor = null;
if (code === 200 && (body.next_image !== undefined)) {
    sensor = {
        payload: next,
        attrs: {
            pool_size:         body.pool_size,
            image_order:       body.image_order,
            print_count:       body.print_count,
            last_print:        body.last_print || body.time || null,
            printer_reachable: body.printer_reachable,
            next_run:          body.next_run ? body.next_run.iso : undefined
        }
    };
}
return [notify, sensor];
